test('createInvoice: VAT exempt product', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  assert.strictEqual(invoice.lines[0].vatRate, 0);
  assert.strictEqual(invoice.lines[0].unitPrice, 60000);
});

test('createInvoice: different VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  assert.strictEqual(invoice.lines[0].vatRate, 21);
  assert.strictEqual(invoice.lines[1].vatRate, 9);
  assert.strictEqual(invoice.lines[2].vatRate, 0);
});

test('lineTotal: single item', () => {
  const line = { qty: 5, unitPrice: 8500 };
  assert.strictEqual(lineTotal(line), 42500);
});

test('lineTotal: qty of 1', () => {
  const line = { qty: 1, unitPrice: 120000 };
  assert.strictEqual(lineTotal(line), 120000);
});

test('lineTotal: large quantity', () => {
  const line = { qty: 1000, unitPrice: 37 };
  assert.strictEqual(lineTotal(line), 37000);
});

test('lineTotal: does not mutate input', () => {
  const line = { qty: 5, unitPrice: 8500 };
  const copy = JSON.stringify(line);
  lineTotal(line);
  assert.strictEqual(JSON.stringify(line), copy);
});

test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, { subtotal: 42500, total: 42500 });
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 2, unitPrice: 980 },
      { qty: 100, unitPrice: 37 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 10 * 9500 + 2 * 980 + 100 * 37;
  assert.strictEqual(totals.subtotal, expected);
  assert.strictEqual(totals.total, expected);
});

test('invoiceTotals: equal subtotal and total (VAT not yet implemented)', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000 },
      { qty: 1, unitPrice: 245000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, totals.total);
  assert.strictEqual(totals.subtotal, 365000);
});

test('invoiceTotals: does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500 }],
  };
  const copy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.strictEqual(JSON.stringify(invoice), copy);
});

test('invoiceTotals: with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });
  assert.strictEqual(result.ok, true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);
  const expected = 5 * 8500 + 2 * 980;
  assert.strictEqual(totals.subtotal, expected);
  assert.strictEqual(totals.total, expected);
});
